    void escribir(std::ostream& salida) const;
private:
    int codigo_;
};
void MedidaIdentificada::escribir(std::ostream& salida) const {
    // Reutiliza el informe base y agrega el codigo propio en el flujo recibido.
    Medida::escribir(salida);
}
