              << "Heredada:" << heredada.str() << '\n'
              << "Calificada:" << calificada.str() << '\n'
              << "Copia:" << copiada.str() << '\n'
              << "TrasCambio:" << despues.str() << '\n'
              << "CopiaTrasCambio:" << copia_despues.str() << '\n'
              << "Estado:(" << dato.numero() << ',' << dato.codigo() << ')';
